-- Video collections (English Sponge, Bob the Canadian, BBC Learning English), chosen by speaking speed,
-- plus a stored summary per lesson. Run once in Supabase Dashboard -> SQL Editor.

create table if not exists public.collections (
  id text primary key check (id ~ '^[a-z0-9-]{2,20}$'),
  name text not null,
  sort_order integer not null default 0
);

alter table public.collections enable row level security;
create policy "collections_select_all" on public.collections for select to anon, authenticated using (true);

on conflict (id) do nothing;

alter table public.videos
  add column if not exists collection_id text not null default 'sponge' references public.collections (id);
create index if not exists videos_collection_idx on public.videos (collection_id, is_published, sort_order);

alter table public.user_settings
  add column if not exists collection_id text references public.collections (id);

-- { overview, keyPoints[], keyWords[{ word, meaning }], source: 'ai' | 'free' }, filled by scripts/summarize-lessons.ts.
alter table public.lessons add column if not exists summary jsonb;

on conflict (video_id) do nothing;
